cat > /private/tmp/claude-502/-Users-laughedelic-Code-obsidian-true-outliner--claude-worktrees-e2e-test-parallelization-c9b457/648345eb-b193-4447-90c5-59fd9786594a/scratchpad/backlinks-canvas/Main.dc.html <<'HTMLEOF'
<!doctype html>
<html>
<head>
  <meta charset="utf-8">
  <script src="./support.js"></script>
</head>
<body>
<x-dc>
<helmet>
  <style>
    body { margin: 0; }
    a { color: hsl(255, 89.8%, 75.9%); text-decoration: none; }
    a:hover { color: hsl(258, 88%, 66%); text-decoration: underline; }
    .to-root {
      /* Obsidian 1.13.3 dark theme, verbatim */
      --base-00: #1C1C1C; --base-05: #212121; --base-10: #232323; --base-20: #282828;
      --base-25: #2e2e2e; --base-30: #333333; --base-35: #3f3f3f; --base-40: #555555;
      --base-50: #666666; --base-60: #999999; --base-70: #b3b3b3; --base-100: #dadada;
      --bg: var(--base-00); --bg-2: var(--base-20); --border: var(--base-30);
      --hover: rgba(255,255,255,0.067);
      --tx: var(--base-100); --tx-muted: var(--base-70); --tx-faint: var(--base-50);
      --guide: color-mix(in srgb, var(--tx-faint) 60%, transparent);
      --ui-smaller: 12px; --ui-small: 13px; --ui-medium: 15px;
      --unit: 20px;               /* --to-decor-unit scaled to the pane's 13px UI type */
      --gutter: 17px;             /* --to-marker-gutter, same scale */
      --ico: 11px;                /* --to-marker-icon-size, same scale */
      font-family: ui-sans-serif, -apple-system, BlinkMacSystemFont, system-ui, "Segoe UI",
        Roboto, "Inter Variable", "Inter", sans-serif;
      -webkit-font-smoothing: antialiased;
    }
    .to-root *, .to-root *::before, .to-root *::after { box-sizing: border-box; }
    .hdr-btn { cursor: pointer; border-radius: 4px; }
    .hdr-btn:hover { background: var(--hover); }
    .seg-b { cursor: pointer; }
    .grp-h { cursor: pointer; }
    .grp-h:hover { background: var(--hover); }
    .row:hover { background: var(--hover); }
    .fold { cursor: pointer; opacity: 0; transition: opacity 90ms linear; }
    .row:hover .fold { opacity: 1; }
    .fold.on { opacity: 1; }
    .lnk { color: hsl(255, 89.8%, 75.9%); cursor: pointer; }
    .lnk:hover { text-decoration: underline; }
    .scroll::-webkit-scrollbar { width: 10px; }
    .scroll::-webkit-scrollbar-thumb { background: var(--base-30); border-radius: 5px; }
    .scroll::-webkit-scrollbar-track { background: transparent; }
    input.q { outline: none; }
    input.q:focus { border-color: var(--acc); }
    input.q::placeholder { color: var(--tx-faint); }
  </style>
</helmet>

<div class="to-root" style="--acc: {{accent}}; --rowpad: {{rowPad}}; width: 400px; height: 880px; display: flex; flex-direction: column; background: var(--bg); color: var(--tx); overflow: hidden;">

  <!-- pane header: Obsidian --header-height 40px -->
  <div style="display: flex; align-items: center; gap: 8px; height: 40px; padding: 0 8px 0 12px; flex-shrink: 0; border-bottom: 1px solid var(--border);">
    <svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="var(--tx-muted)" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" style="flex-shrink: 0;">
      <path d="M9 17H7A5 5 0 0 1 7 7h2"></path>
      <path d="M15 7h2a5 5 0 1 1 0 10h-2"></path>
      <line x1="8" y1="12" x2="16" y2="12"></line>
    </svg>
    <div style="font-size: var(--ui-small); font-weight: 600; color: var(--tx-muted); letter-spacing: 0.01em; flex-grow: 1;">Structured backlinks</div>
    <div class="hdr-btn" style="width: 24px; height: 24px; display: flex; align-items: center; justify-content: center;">
      <svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="var(--tx-faint)" stroke-width="2" stroke-linecap="round" aria-hidden="true">
        <circle cx="5" cy="12" r="1"></circle><circle cx="12" cy="12" r="1"></circle><circle cx="19" cy="12" r="1"></circle>
      </svg>
    </div>
  </div>

  <!-- subject -->
  <div style="padding: 12px 12px 0 12px; flex-shrink: 0;">
    <div style="display: flex; align-items: baseline; gap: 8px;">
      <div style="font-size: var(--ui-medium); font-weight: 600; color: var(--tx); flex-grow: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">Aurora Dashboard</div>
      <div style="font-size: var(--ui-smaller); color: var(--tx-faint); white-space: nowrap;">{{totals}}</div>
    </div>
    <div style="display: flex; align-items: center; gap: 6px; margin-top: 3px;">
      <svg viewBox="0 0 16 16" width="10" height="10" fill="none" stroke="var(--tx-faint)" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
        <path d="M2 4.5 A1.5 1.5 0 0 1 3.5 3h3l1.2 1.6H12.5A1.5 1.5 0 0 1 14 6.1v5.4A1.5 1.5 0 0 1 12.5 13h-9A1.5 1.5 0 0 1 2 11.5z"></path>
      </svg>
      <div style="font-size: var(--ui-smaller); color: var(--tx-faint);">Projects / Aurora Dashboard.md</div>
    </div>
  </div>

  <!-- controls -->
  <div style="display: flex; flex-direction: column; gap: 8px; padding: 12px; flex-shrink: 0;">
    <div style="display: flex; align-items: center; gap: 8px;">
      <div style="position: relative; flex-grow: 1; display: flex; align-items: center;">
        <svg viewBox="0 0 16 16" width="12" height="12" fill="none" stroke="var(--tx-faint)" stroke-width="1.7" stroke-linecap="round" aria-hidden="true" style="position: absolute; left: 8px;">
          <circle cx="7" cy="7" r="4.5"></circle><line x1="10.5" y1="10.5" x2="14" y2="14"></line>
        </svg>
        <input class="q" type="text" value="{{q}}" onChange="{{onFilter}}" placeholder="Filter references"
          style="width: 100%; height: 28px; padding: 0 8px 0 25px; font-size: var(--ui-small); font-family: inherit; color: var(--tx); background: var(--base-25); border: 1px solid var(--border); border-radius: 4px;">
      </div>
      <div class="hdr-btn" onClick="{{cycleSort}}" title="Sort order"
        style="height: 28px; display: flex; align-items: center; gap: 5px; padding: 0 8px; font-size: var(--ui-smaller); color: var(--tx-muted); background: var(--base-25); border: 1px solid var(--border); white-space: nowrap;">
        <svg viewBox="0 0 16 16" width="11" height="11" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
          <line x1="3" y1="4" x2="13" y2="4"></line><line x1="3" y1="8" x2="10" y2="8"></line><line x1="3" y1="12" x2="7" y2="12"></line>
        </svg>{{sortLabel}}
      </div>
    </div>

    <div style="display: flex; align-items: center; gap: 8px;">
      <div style="font-size: var(--ui-smaller); color: var(--tx-faint); white-space: nowrap;">Context</div>
      <div style="display: flex; background: var(--base-25); border: 1px solid var(--border); border-radius: 4px; padding: 2px; gap: 2px; flex-grow: 1;">
        <sc-for list="{{ctxOpts}}" as="o" hint-placeholder-count="3">
          <div class="seg-b" onClick="{{o.pick}}"
            style="flex-grow: 1; text-align: center; font-size: var(--ui-smaller); line-height: 20px; border-radius: 3px; color: {{o.fg}}; background: {{o.bg}};">{{o.label}}</div>
        </sc-for>
      </div>
