class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = { ctx: 'spine', kids: true, q: '', sort: 0, folded: {}, closed: {}, hover: null };
  }

  data() {
    const T = (text) => ({ text, plain: true, link: false });
    const L = (text) => ({ text, plain: false, link: true });
    return [
      {
        id: 'g1', name: '2026-07-10', when: 3,
        nodes: [
          { k: 'a1', d: 0, kind: 'heading', role: 'anc', parts: [T('Aurora review')] },
          { k: 'h1', d: 1, kind: 'para', role: 'hit', parts: [T('Decisions that came out of the '), L('Aurora Dashboard'), T(' review:')] },
          { k: 'h1a', d: 2, kind: 'bullet', role: 'kid', of: 'h1', parts: [T('severity-first layout approved')] },
          { k: 'h1b', d: 2, kind: 'bullet', role: 'kid', of: 'h1', parts: [T('the timestamp-on-hover idea needs a fallback for touch devices')] },
          { k: 'h1c', d: 2, kind: 'bullet', role: 'kid', of: 'h1', parts: [T('ship the triage view behind a flag next sprint')] },
          { k: 'h2', d: 1, kind: 'callout', role: 'hit', parts: [T('Legal wants a review of the '), L('Aurora Dashboard'), T(' alarm-name field — some customers put PII in there.')] }
        ]
      },
      {
        id: 'g2', name: 'Reading – The Design of Everyday Things', when: 5,
        nodes: [
          { k: 'a1', d: 0, kind: 'bullet', role: 'anc', parts: [T('affordances vs signifiers')], cont: 'the thing you CAN do vs the thing that TELLS you what you can do' },
          { k: 'h1', d: 1, kind: 'bullet', role: 'hit', parts: [T('the '), L('Aurora Dashboard'), T(' timestamp column is a Norman door: it affords sorting, signifies nothing')] }
        ]
      },
      {
        id: 'g3', name: '2026-07-07', when: 6,
        nodes: [
          { k: 'h1', d: 0, kind: 'para', role: 'hit', parts: [T('The '), L('Aurora Dashboard'), T(' review got pushed to Wednesday because '), L('Maya Lindqvist'), T(" is out sick. Honestly a relief — the navigation flows aren't ready and I'd rather show something I believe in.")] }
        ]
      },
      {
        id: 'g4', name: 'Maya Lindqvist', when: 12,
        nodes: [
          { k: 'h1', d: 0, kind: 'para', role: 'hit', parts: [T('Design lead on '), L('Aurora Dashboard'), T('. The person to convince first — if Maya buys an idea, the room follows.')] }
        ]
      },
      {
        id: 'g5', name: 'Priya Nair', when: 14,
        nodes: [
          { k: 'h1', d: 0, kind: 'para', role: 'hit', parts: [T('Analyst on '), L('Aurora Dashboard'), T('. Ran the user-session study that produced the severity-scanning insight — the best research finding of the quarter.')] }
        ]
