  renderVals() {
    const acc = this.props.accent ?? '#a68af9';
    const compact = (this.props.density ?? 'comfortable') === 'compact';
    const { ctx, kids, q, sort, folded, closed, hover } = this.state;
    const faint = '#666666', muted = '#b3b3b3', normal = '#dadada';
    const guide = 'color-mix(in srgb, #666666 60%, transparent)';
    const needle = q.trim().toLowerCase();

    const textOf = (n) => n.parts.map((p) => p.text).join('') + (n.cont ? ' ' + n.cont : '');

    const sorted = this.data().slice();
    if (sort === 1) sorted.sort((a, b) => b.when - a.when);
    if (sort === 2) sorted.sort((a, b) => a.name.localeCompare(b.name));

    const groups = [];
    for (const g of sorted) {
      const hitCount = g.nodes.filter((n) => n.role === 'hit').length;
      if (needle && !g.name.toLowerCase().includes(needle) &&
          !g.nodes.some((n) => textOf(n).toLowerCase().includes(needle))) continue;

      const isClosed = !!closed[g.id];
      const rows = [];

      if (!isClosed) {
        // ancestor chain per hit, from the flat node list
        const ancFor = (i) => {
          const out = [];
          let want = g.nodes[i].d - 1;
          for (let j = i - 1; j >= 0 && want >= 0; j--) {
            if (g.nodes[j].role !== 'kid' && g.nodes[j].d === want) { out.unshift(g.nodes[j]); want--; }
          }
          return out;
        };

        const emitted = {};
        g.nodes.forEach((n, i) => {
          if (n.role === 'anc') {
            if (ctx === 'spine') rows.push({ ...n, dd: n.d });
            return;
          }
          if (n.role === 'kid') {
            if (!kids || folded[g.id + n.of]) return;
            const host = g.nodes.find((m) => m.k === n.of);
            const base = ctx === 'spine' ? host.d : 0;
            rows.push({ ...n, dd: base + (n.d - host.d) });
            return;
          }
          // hit
          const chain = ancFor(i);
          if (ctx === 'path' && chain.length) {
            rows.push({
              k: n.k + '-crumb', kind: 'crumb', role: 'crumb', dd: 0,
              parts: [{ text: chain.map((c) => c.parts.map((p) => p.text).join('')).join('  ›  '), plain: true, link: false }]
            });
          }
          rows.push({ ...n, dd: ctx === 'spine' ? n.d : 0 });
        });
      }

      const hovered = hover && hover.g === g.id ? g.nodes.find((n) => n.k === hover.k) : null;
      const litKeys = {};
      if (hovered) {
        let want = hovered.d - 1;
        const idx = g.nodes.findIndex((n) => n.k === hovered.k);
        for (let j = idx - 1; j >= 0 && want >= 0; j--) {
          if (g.nodes[j].role !== 'kid' && g.nodes[j].d === want) { litKeys[g.nodes[j].k] = true; want--; }
        }
        litKeys[hovered.k] = true;
        g.nodes.forEach((n) => { if (n.role === 'kid' && n.of === hovered.k) litKeys[n.k] = true; });
      }

      groups.push({
        id: g.id, name: g.name, count: hitCount,
        rot: isClosed ? 0 : 90,
        toggle: () => this.setState({ closed: { ...closed, [g.id]: !closed[g.id] } }),
        rows: rows.map((r) => {
          const lit = !!litKeys[r.k];
          const isHit = r.role === 'hit';
          const isAnc = r.role === 'anc';
          const isCrumb = r.role === 'crumb';
          const nKids = g.nodes.filter((n) => n.role === 'kid' && n.of === r.k).length;
          const isFolded = !!folded[g.id + r.k];
          return {
            rails: Array.from({ length: isCrumb ? 0 : r.dd }, () => ({ color: lit ? acc : guide })),
            isHeading: r.kind === 'heading', isPara: r.kind === 'para',
            isCallout: r.kind === 'callout', isBullet: r.kind === 'bullet',
            isCrumb, isTask: !!r.task,
            mkColor: isHit ? acc : lit ? acc : r.kind === 'callout' ? muted : faint,
            mkTop: r.kind === 'bullet' ? (compact ? '7px' : '8px') : (compact ? '4px' : '5px'),
            parts: r.parts,
            fs: isCrumb ? '11px' : '13px',
            lh: compact ? '1.4' : '1.52',
            fg: isHit ? normal : isCrumb ? faint : lit ? muted : faint,
            fw: isHit ? '400' : isAnc && r.kind === 'heading' ? '600' : '400',
            contFg: lit ? muted : faint,
            hasCont: !!r.cont, cont: r.cont ?? '',
            rowBg: isHit && lit ? 'color-mix(in srgb, ' + acc + ' 9%, transparent)' : 'transparent',
            canFold: isHit && kids && nKids > 0,
            foldCls: isFolded ? 'on' : '',
            foldRot: isFolded ? 0 : 90,
            toggleFold: () => this.setState({ folded: { ...folded, [g.id + r.k]: !folded[g.id + r.k] } }),
            enter: () => { if (isHit) this.setState({ hover: { g: g.id, k: r.k } }); },
            leave: () => { if (isHit) this.setState({ hover: null }); }
          };
        })
      });
    }

    const total = groups.reduce((s, g) => s + g.count, 0);
    const segs = [['spine', 'Spine'], ['path', 'Path'], ['none', 'None']];

    return {
      accent: acc,
      rowPad: compact ? '1px' : '3px',
      totals: total + (total === 1 ? ' reference' : ' references') + ' · ' + groups.length + ' notes',
      q, empty: groups.length === 0,
      onFilter: (e) => this.setState({ q: e.target.value }),
      sortLabel: ['Recent', 'Oldest', 'Name'][sort],
      cycleSort: () => this.setState({ sort: (sort + 1) % 3 }),
      ctxOpts: segs.map(([id, label]) => ({
        label, fg: ctx === id ? '#1C1C1C' : muted,
        bg: ctx === id ? acc : 'transparent',
        pick: () => this.setState({ ctx: id })
      })),
      kidsFg: kids ? acc : faint,
      kidsBorder: kids ? acc : '#333333',
      kidsBg: kids ? 'color-mix(in srgb, ' + acc + ' 14%, transparent)' : 'transparent',
      toggleKids: () => this.setState({ kids: !kids }),
      groups
    };
  }
}
