  "frameW": {"editor": "range", "default": 660, "min": 380, "max": 860, "step": 20, "unit": "px", "section": "Pressure test"}
}'>
class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = { kase: 'deep' };
  }

  cases() {
    const T = (text) => ({ text, plain: true, link: false });
    const L = (text) => ({ text, plain: false, link: true });
    return {
      deep: {
        label: 'Deep chain',
        note: '2026-07-12 · one reference four levels down, with a long multi-line ancestor',
        spine: [{
          k: 'a1', kind: 'bullet', parts: [T('work')],
          children: [{
            k: 'a2', kind: 'bullet', parts: [T('Aurora')],
            children: [{
              k: 'a3', kind: 'bullet', parts: [T('prototype review, second pass')],
              cont: 'the severity sort must be stable or rows jump under the cursor — this is the bug Maya kept hitting all through the demo',
              children: [{
                k: 'h1', kind: 'bullet', hit: true,
                parts: [T('keep the timestamp on hover only, and note it in '), L('Aurora Dashboard')]
              }]
            }]
          }]
        }]
      },
      branch: {
        label: 'Branching',
        note: '2026-07-10 · two references under one heading — the lineage must not squash away the split',
        spine: [{
          k: 'a1', kind: 'heading', parts: [T('Aurora review')],
          children: [
            { k: 'h1', kind: 'para', hit: true, parts: [T('Decisions that came out of the '), L('Aurora Dashboard'), T(' review:')] },
            { k: 'h2', kind: 'callout', hit: true, parts: [T('Legal wants a review of the '), L('Aurora Dashboard'), T(' alarm-name field — some customers put PII in there.')] }
          ]
        }]
      }
    };
  }

  head(n) { return n.parts.map((p) => p.text).join(''); }

  clip(s, max) {
    if (s.length <= max) return s;
    const keep = max - 1;
    return s.slice(0, Math.ceil(keep * 0.6)) + '…' + s.slice(s.length - Math.floor(keep * 0.4));
  }

  build(spine, opts) {
    const acc = this.props.accent ?? '#a68af9';
    const faint = '#666666', normal = '#dadada';
    const rows = [];

    const rails = (d) => Array.from({ length: d }, () => ({}));

    const nodeRow = (n, d, isHit) => rows.push({
      isNode: true, isCrumbSegs: false, isCrumbLine: false,
      rails: rails(d),
      isHeading: n.kind === 'heading', isPara: n.kind === 'para',
      isCallout: n.kind === 'callout', isBullet: n.kind === 'bullet',
      mkColor: isHit ? acc : faint, mkTop: n.kind === 'bullet' ? '9px' : '6px',
      parts: n.parts, fg: isHit ? normal : faint,
      fw: n.kind === 'heading' ? '700' : '400',
      hasCont: !!n.cont && opts.cont === 'full', cont: n.cont ?? ''
    });

    const crumbRow = (segs, d) => {
      if (opts.clip === 'line') {
        rows.push({
          isCrumbLine: true, isCrumbSegs: false, isNode: false,
          rails: rails(d), line: segs.map((s) => this.head(s)).join('  ›  ')
        });
        return;
      }
      rows.push({
        isCrumbSegs: true, isCrumbLine: false, isNode: false,
        rails: rails(d),
        segs: segs.map((s, i) => ({
          short: opts.clip === 'seg' ? this.clip(this.head(s), 30) : this.head(s),
          full: this.head(s), sep: i < segs.length - 1
        }))
      });
    };

    const emit = (nodes, d) => {
      nodes.forEach((n) => {
        if (opts.mode !== 'ladder' && !n.hit && (n.children ?? []).length >= 1) {
          const chain = [n];
          let cur = n;
          while (!cur.hit && (cur.children ?? []).length === 1) { cur = cur.children[0]; chain.push(cur); }
          const last = chain[chain.length - 1];
          const segs = last.hit ? chain.slice(0, -1) : chain;
          if (segs.length) crumbRow(segs, d);
          const nd = segs.length ? (opts.mode === 'hang' ? d : d + 1) : d;
          if (last.hit) nodeRow(last, nd, true); else emit(last.children, nd);
          return;
        }
        if (n.hit) { nodeRow(n, d, true); return; }
        nodeRow(n, d, false);
        emit(n.children ?? [], d + 1);
      });
    };

    emit(spine, 0);
    return rows;
  }

  renderVals() {
    const acc = this.props.accent ?? '#a68af9';
    const muted = '#b3b3b3';
    const kase = this.state.kase;
    const all = this.cases();
    const active = all[kase];

    const defs = [
      { id: 'A', name: 'Ladder, verbatim', note: 'today’s Spine. Every ancestor a row, continuation lines and all.', mode: 'ladder', cont: 'full', clip: 'none' },
      { id: 'B', name: 'Ladder, first line', note: 'same shape; a multi-line ancestor contributes only its first line.', mode: 'ladder', cont: 'first', clip: 'none' },
      { id: 'C', name: 'Squashed', note: 'single-child runs become one lineage line; the tree splits only where it branches.', mode: 'squash', cont: 'first', clip: 'none' },
      { id: 'D', name: 'Squashed + clipped segments', note: 'each segment gets a character budget, middle-elided. Hover restores it.', mode: 'squash', cont: 'first', clip: 'seg', pick: true },
      { id: 'E', name: 'Squashed + one line', note: 'the whole lineage is one clipped line — the tail is lost, not the middle.', mode: 'squash', cont: 'first', clip: 'line' },
      { id: 'F', name: 'Hanging lineage', note: 'lineage sits above at zero indent; the reference keeps the full width.', mode: 'hang', cont: 'first', clip: 'seg' }
    ];

    return {
      accent: acc,
      frameW: this.props.frameW ?? 660,
      caseNote: active.note,
      cases: Object.keys(all).map((id) => ({
        label: all[id].label,
        fg: kase === id ? '#1C1C1C' : muted,
        bg: kase === id ? acc : 'transparent',
        pick: () => this.setState({ kase: id })
      })),
      variants: defs.map((d) => {
        const rows = this.build(active.spine, d);
        const maxDepth = rows.reduce((m, r) => Math.max(m, r.rails.length), 0);
        return {
          name: d.name, note: d.note,
          isPick: !!d.pick,
          nameFg: d.pick ? acc : '#dadada',
          border: d.pick ? 'color-mix(in srgb, ' + acc + ' 40%, transparent)' : '#282828',
          bg: '#212121',
          headBg: d.pick ? 'color-mix(in srgb, ' + acc + ' 8%, transparent)' : '#1C1C1C',
          cost: rows.length + ' rows · ' + maxDepth * 24 + 'px indent',
          rows
        };
      })
    };
  }
}
</script>
</body>
