    const acc = this.props.accent ?? '#a68af9';
    const defs = [
      { name: 'Ladder', note: 'every ancestor its own row — the baseline this replaces.', mode: 'ladder', clip: 'none' },
      { name: 'Squashed, verbatim', note: 'single-child runs become one line of inline text, nothing shortened. Wraps like prose when it has to.', mode: 'squash', clip: 'none', pick: true },
      { name: 'Squashed, long segments only', note: 'only a segment past 60 characters is elided — short ancestors always read in full.', mode: 'squash', clip: 'long' },
      { name: 'Squashed, every segment', note: 'a 26-character budget on all of them. Compact, but shows a bit of everything and enough of nothing.', mode: 'squash', clip: 'seg' },
      { name: 'Hanging lineage', note: 'lineage at zero indent; the reference keeps the full width but loses its nesting.', mode: 'hang', clip: 'none' }
    ];
    const kases = this.cases();

    return {
      accent: acc,
      frameW: this.props.frameW ?? 760,
      variants: defs.map((d) => ({
        name: d.name, note: d.note,
        isPick: !!d.pick,
        nameFg: d.pick ? acc : '#dadada',
        border: d.pick ? 'color-mix(in srgb, ' + acc + ' 40%, transparent)' : '#282828',
        headBg: d.pick ? 'color-mix(in srgb, ' + acc + ' 8%, transparent)' : '#1C1C1C',
        cases: kases.map((k, i) => {
          const rows = this.build(k.spine, d);
          const maxDepth = rows.reduce((m, r) => Math.max(m, r.rails.length), 0);
          return {
            label: k.label,
            cost: rows.length + ' rows · ' + maxDepth * 24 + 'px indent',
            sep: i === 0 ? 'transparent' : '#282828',
            rows
          };
        })
      }))
    };
  }
}
